+const MAX_RETRIES = 3;
+const BACKOFF_MS = 200;
+
+// Retries 503s and dropped connections (fetch rejecting) up to 3 times, with
+// exponential backoff. Other statuses (incl. 4xx) fail immediately.
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (attempt >= MAX_RETRIES) throw err;
+      await sleep(BACKOFF_MS * 2 ** attempt);
+      continue;
+    }
+    if (res.status === 503 && attempt < MAX_RETRIES) {
+      await sleep(BACKOFF_MS * 2 ** attempt);
+      continue;
+    }
+    if (!res.ok) throw new HttpError(res.status, url);
+    return res.json();
+  }
